CREATE TABLE IF NOT EXISTS users (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password VARCHAR(256) NOT NULL, mobile VARCHAR(20) DEFAULT '', role VARCHAR(20) NOT NULL DEFAULT 'CUSTOMER', status BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, description VARCHAR(500) DEFAULT '', status BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS products (id BIGINT AUTO_INCREMENT PRIMARY KEY, category_id BIGINT NOT NULL, name VARCHAR(150) NOT NULL, brand VARCHAR(100) NOT NULL, description VARCHAR(2000) NOT NULL, price DECIMAL(12,2) NOT NULL, discount DECIMAL(5,2) DEFAULT 0, stock INT NOT NULL, image_url VARCHAR(500) NOT NULL, status BOOLEAN DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(category_id) REFERENCES categories(id), CHECK(price > 0), CHECK(stock >= 0), CHECK(discount >= 0 AND discount < 100));
CREATE TABLE IF NOT EXISTS addresses (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, address_line VARCHAR(300) NOT NULL, city VARCHAR(100) NOT NULL, state VARCHAR(100) NOT NULL, pincode VARCHAR(10) NOT NULL, address_type VARCHAR(20) DEFAULT 'Home', FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS cart (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, product_id BIGINT NOT NULL, quantity INT NOT NULL, UNIQUE(user_id, product_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(product_id) REFERENCES products(id), CHECK(quantity BETWEEN 1 AND 99));
CREATE TABLE IF NOT EXISTS wishlist (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, product_id BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id, product_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS coupons (id BIGINT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, discount_type VARCHAR(20) NOT NULL, discount_value DECIMAL(10,2) NOT NULL, minimum_order DECIMAL(12,2) DEFAULT 0, maximum_discount DECIMAL(12,2) NOT NULL, expiry_date DATE NOT NULL, status BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS orders (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, address_id BIGINT NOT NULL, shipping_address VARCHAR(700) NOT NULL, subtotal DECIMAL(12,2) NOT NULL, discount DECIMAL(12,2) NOT NULL, total_amount DECIMAL(12,2) NOT NULL, payment_method VARCHAR(30) NOT NULL, payment_status VARCHAR(30) NOT NULL, order_status VARCHAR(30) NOT NULL, checkout_token VARCHAR(100) NOT NULL UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(address_id) REFERENCES addresses(id));
CREATE TABLE IF NOT EXISTS order_items (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL, product_id BIGINT NOT NULL, product_name VARCHAR(150) NOT NULL, quantity INT NOT NULL, price DECIMAL(12,2) NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS payments (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL UNIQUE, payment_method VARCHAR(30) NOT NULL, transaction_reference VARCHAR(100) NOT NULL, amount DECIMAL(12,2) NOT NULL, payment_status VARCHAR(30) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE IF NOT EXISTS reviews (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, product_id BIGINT NOT NULL, rating INT NOT NULL, review_text VARCHAR(1500) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,product_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(product_id) REFERENCES products(id), CHECK(rating BETWEEN 1 AND 5));
CREATE TABLE IF NOT EXISTS coupon_usage (id BIGINT AUTO_INCREMENT PRIMARY KEY, coupon_id BIGINT NOT NULL, user_id BIGINT NOT NULL, order_id BIGINT NOT NULL UNIQUE, used_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(coupon_id,user_id), FOREIGN KEY(coupon_id) REFERENCES coupons(id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(order_id) REFERENCES orders(id));
